def mean_probability(xs):
    if not xs or any(x<0 or x>1 for x in xs):
        raise ValueError("invalid probabilities")
    return sum(xs)/len(xs)

def validate_batch(features,labels):
    assert len(features)==len(labels)
    if features:
        assert all(len(row)==len(features[0]) for row in features)
    assert all(type(x) is int and x>=0 for x in labels)
    return True

import json
def read_config(path):
    try:
        with open(path,encoding="utf-8") as f:c=json.load(f)
    except json.JSONDecodeError:
        return None
    return {"name":c["name"],"lr":c.get("lr",0.001)}

import torch
def clip_gradients(parameters,max_norm):
    grads=[p.grad for p in parameters if p.grad is not None]
    if not grads:
        return 0.0
    total=torch.sqrt(sum((g*g).sum() for g in grads))
    scale=max_norm/(total.item()+1e-6)
    with torch.no_grad():
        for g in grads:
            g.mul_(scale)
    return total.item()

import torch
def collate_samples(samples):
    if not samples: raise ValueError("empty batch")
    x= samples[0][0].unsqueeze(0) if len(samples)==1 else torch.stack([s[0] for s in samples])
    return x,torch.tensor([s[1] for s in samples],dtype=torch.long)
